// Player rules hard-coded in the SDK (tf_shareddefs.h, tf_player.cpp, tf_player_shared.cpp).

/** Health regeneration (CTFPlayer::RegenThink; TF_REGEN_TIME / TF_REGEN_AMOUNT). */
export const HEALTH_REGEN = {
  /** One regen tick per second. */
  interval: 1.0,
  /** Medic base: 3 HP per tick... */
  medicAmount: 3,
  /** ...+3 while healing a patient below max health... */
  medicHealingBonus: 3,
  /** ...then × 1 → 2 as time since he was last hurt goes 5 s → 10 s (3 → 6 HP/s alone). */
  medicRampStart: 5,
  medicRampEnd: 10,
  medicRampMaxMult: 2,
} as const;

/** Medic regen per tick (fractions accumulate until whole HP are added). */
export function medicRegenPerTick(timeSinceDamage: number, healingHurtPatient: boolean): number {
  const t = Math.min(1, Math.max(0, (timeSinceDamage - HEALTH_REGEN.medicRampStart) / (HEALTH_REGEN.medicRampEnd - HEALTH_REGEN.medicRampStart)));
  const scale = 1 + (HEALTH_REGEN.medicRampMaxMult - 1) * t;
  const base = HEALTH_REGEN.medicAmount + (healingHurtPatient ? HEALTH_REGEN.medicHealingBonus : 0);
  return base * scale;
}

/** Overheal (tf_player_shared.cpp GetMaxBuffedHealth, ConditionThink). */
export const OVERHEAL = {
  /** tf_max_health_boost. */
  maxMult: 1.5,
  /** The cap is rounded down to a multiple of 5 (iRoundDown). */
  roundTo: 5,
  /** tf_boost_drain_time: a full boost (max buffed − max health) drains in 15 s. */
  drainTime: 15,
} as const;

/** Max overheal for a max health (125 → 185, 150 → 225, 175 → 260, 200 → 300, 300 → 450). */
export function maxBuffedHealth(maxHealth: number): number {
  return Math.floor((maxHealth * OVERHEAL.maxMult) / OVERHEAL.roundTo) * OVERHEAL.roundTo;
}

/** Speed rules (CTFPlayer::TeamFortress_CalculateMaxSpeed). */
export const SPEED_RULES = {
  /** Zoomed Sniper (TF_COND_AIMING). */
  sniperAiming: 80,
  /** Spun-up Heavy (TF_COND_AIMING). */
  heavyAiming: 110,
  /** Disguised Spies move no faster than the disguise class. Carrying a building: × 0.9. */
  carryingBuildingMult: 0.9,
  /** Bonus round (GR_STATE_TEAM_WIN): winners × 1.1, losers × 0.9. */
  winnerMult: 1.1,
  loserMult: 0.9,
  /** tf_spy_max_cloaked_speed: no cap. */
  cloakedMax: 999,
} as const;

